class AsyncPlayers:
    """Players: search, look up, warn, ban, kick, message, notes, whitelist."""

    def __init__(self, client: AsyncRequester) -> None:
        self._client = client

    async def search(
        self,
        *,
        query: str | None = None,
        sort_by: str | None = None,
        order: str | None = None,
        filters: str | Sequence[str] | None = None,
        offset: int | None = None,
        cursor: str | None = None,
        server_id: int | str | None = None,
        timeout: float | None = None,
    ) -> t.PlayerPage:
        """Search players by display name (one page of at most 100 rows).

        Without ``query`` the complete, sorted player list. Use :meth:`iter_search` to page
        through all results automatically.

        Permission: ``players.read``.
        Endpoint: ``GET /api/v1/players/search``.

        Args:
            query: Part of the display name; omit to list every player.
            sort_by: ``playTime`` (default), ``tsJoined`` or ``tsLastConnection``.
            order: ``asc`` or ``desc`` (default ``desc``).
            filters: Quick filters ``isOnline``, ``isAdmin``, ``isWhitelisted``, ``hasNote``
                (comma-separated string or sequence).
            offset: Cursor: sort-key value of the last row of the previous page (with
                ``cursor``).
            cursor: Cursor: ``license`` of the last row of the previous page (with ``offset``).
            server_id: Server to address; defaults to the client's ``server_id``.
            timeout: Per-attempt timeout in seconds; defaults to the client's.
        """
        return cast(
            "t.PlayerPage",
            (
                await self._client._request(
                    _E["players.search"],
                    path={},
                    query={
                        "query": query,
                        "sortBy": sort_by,
                        "order": order,
                        "filters": filters,
                        "offset": offset,
                        "cursor": cursor,
                    },
                    body=None,
                    server_id=server_id,
                    timeout=timeout,
                )
            ).data,
        )

    def iter_search(
        self,
        *,
        query: str | None = None,
        sort_by: str | None = None,
        order: str | None = None,
        filters: str | Sequence[str] | None = None,
        server_id: int | str | None = None,
        timeout: float | None = None,
    ) -> AsyncIterator[t.PlayerRow]:
        """Iterate over all player rows of :meth:`search`, fetching pages lazily.

        Stops when the API reports the end, the cursor is missing or a page is empty.

        Permission: ``players.read``.
        Endpoint: ``GET /api/v1/players/search``.

        Args:
            query: Part of the display name; omit to list every player.
            sort_by: ``playTime`` (default), ``tsJoined`` or ``tsLastConnection``.
            order: ``asc`` or ``desc`` (default ``desc``).
            filters: Quick filters ``isOnline``, ``isAdmin``, ``isWhitelisted``, ``hasNote``
                (comma-separated string or sequence).
            server_id: Server to address; defaults to the client's ``server_id``.
            timeout: Per-attempt timeout in seconds; defaults to the client's.
        """

        async def fetch(offset: int | None, cursor: str | None) -> t.PlayerPage:
            return await self.search(
                query=query,
                sort_by=sort_by,
                order=order,
                filters=filters,
                offset=offset,
                cursor=cursor,
                server_id=server_id,
                timeout=timeout,
            )

        return _pagination.aiter_players(fetch, _pagination.player_sort_key(sort_by))

