class AsyncConsole:
    """Live console: buffer, commands and the live stream."""

    def __init__(self, client: AsyncRequester) -> None:
        self._client = client

    async def buffer(
        self, *, server_id: int | str | None = None, timeout: float | None = None
    ) -> t.ConsoleBuffer:
        """Return the last 500 console lines (with FXServer's ANSI colour codes).

        Permission: ``console.write``.
        Endpoint: ``GET /api/v1/console``.

        Args:
            server_id: Server to address; defaults to the client's ``server_id``.
            timeout: Per-attempt timeout in seconds; defaults to the client's.
        """
        return cast(
            "t.ConsoleBuffer",
            (
                await self._client._request(
                    _E["console.buffer"],
                    path={},
                    query={},
                    body=None,
                    server_id=server_id,
                    timeout=timeout,
                )
            ).data,
        )

    async def command(
        self, *, command: str, server_id: int | str | None = None, timeout: float | None = None
    ) -> t.MutationResult:
        """Run a console command.

        Fire-and-forget: success only means txAdmin accepted the command. Read the output via
        :meth:`buffer` or the live stream (:meth:`connect`).

        Permission: ``console.write``.
        Endpoint: ``POST /api/v1/console/command``.

        Args:
            command: FXServer / txAdmin console command. At most 1024 characters.
            server_id: Server to address; defaults to the client's ``server_id``.
            timeout: Per-attempt timeout in seconds; defaults to the client's.
        """
        return cast(
            "t.MutationResult",
            (
                await self._client._request(
                    _E["console.command"],
                    path={},
                    query={},
                    body={"command": command},
                    server_id=server_id,
                    timeout=timeout,
                )
            ).data,
        )

    def connect(
        self,
        *,
        server_id: int | str | None = None,
        raw_frames: bool = False,
        on_event: Callable[[t_live.ConsoleEvent], Any] | None = None,
        reconnect: bool = True,
        max_reconnect_attempts: int | None = None,
        initial_reconnect_delay: float = 1.0,
        max_reconnect_delay: float = 30.0,
        open_timeout: float = 10.0,
        command_timeout: float = 10.0,
    ) -> t_live.ConsoleStream:
        """Open the live console stream (``/ws/console``).

        Yields :data:`txapi.live.ConsoleEvent` values and offers
        :meth:`~txapi.live.ConsoleStream.send_command`.

        Use it inside a running event loop: ``async with client.console.connect() as s:``.
        Needs the optional ``websockets`` dependency (``pip install "txapi-sdk[live]"``).

        Permission: ``console.write``. Endpoint: ``WS /ws/console``.

        Args:
            server_id: Server to stream; defaults to the client's ``server_id``.
            raw_frames: Also emit every raw frame as :class:`~txapi.live.FrameEvent`.
            on_event: Callback (sync or async) called for every event.
            reconnect: Reconnect after 1001/1006/1011/1012 and network loss (never 1008/1009).
            max_reconnect_attempts: Give up after this many attempts in a row (``None`` = never).
            initial_reconnect_delay: First backoff delay in seconds (doubles, with jitter).
            max_reconnect_delay: Backoff ceiling in seconds.
            open_timeout: Handshake timeout in seconds.
            command_timeout: How long ``send_command`` waits for the ack.
        """
        return t_live.ConsoleStream(
            self._client._live_config(server_id),
            raw_frames=raw_frames,
            on_event=on_event,
            reconnect=reconnect,
            max_reconnect_attempts=max_reconnect_attempts,
            initial_reconnect_delay=initial_reconnect_delay,
            max_reconnect_delay=max_reconnect_delay,
            open_timeout=open_timeout,
            command_timeout=command_timeout,
        )


