class AsyncGroups:
    """Endpoint groups of the client."""

    account: AsyncAccount
    """Account-level calls (no server involved).
    """
    players: AsyncPlayers
    """Players: search, look up, warn, ban, kick, message, notes, whitelist.
    """
    history: AsyncHistory
    """Ban and warning history.
    """
    server: AsyncServer
    """Server control: status, restart, scheduling, announcements, resources.
    """
    console: AsyncConsole
    """Live console: buffer, commands and the live stream.
    """
    serverlog: AsyncServerLog
    """Server log (joins, leaves, deaths, chat): buffer, history, live stream.
    """
    events: AsyncEvents
    """Stored event log: deaths, kills, chat, admin actions, statistics.
    """
    whitelist: AsyncWhitelist
    """Whitelist requests and advance approvals.
    """
    admins: AsyncAdmins
    """txAdmin panel admin accounts.
    """

    def __init__(self, client: AsyncRequester) -> None:
        self.account = AsyncAccount(client)
        self.players = AsyncPlayers(client)
        self.history = AsyncHistory(client)
        self.server = AsyncServer(client)
        self.console = AsyncConsole(client)
        self.serverlog = AsyncServerLog(client)
        self.events = AsyncEvents(client)
        self.whitelist = AsyncWhitelist(client)
        self.admins = AsyncAdmins(client)


