class AsyncTxApiWithRawResponse:
    """Same methods as the client, returning :class:`~txapi.ApiResponse` objects."""

    account: AsyncAccountWithRawResponse
    """Account-level calls (no server involved).
    """
    players: AsyncPlayersWithRawResponse
    """Players: search, look up, warn, ban, kick, message, notes, whitelist.
    """
    history: AsyncHistoryWithRawResponse
    """Ban and warning history.
    """
    server: AsyncServerWithRawResponse
    """Server control: status, restart, scheduling, announcements, resources.
    """
    console: AsyncConsoleWithRawResponse
    """Live console: buffer, commands and the live stream.
    """
    serverlog: AsyncServerLogWithRawResponse
    """Server log (joins, leaves, deaths, chat): buffer, history, live stream.
    """
    events: AsyncEventsWithRawResponse
    """Stored event log: deaths, kills, chat, admin actions, statistics.
    """
    whitelist: AsyncWhitelistWithRawResponse
    """Whitelist requests and advance approvals.
    """
    admins: AsyncAdminsWithRawResponse
    """txAdmin panel admin accounts.
    """

    def __init__(self, client: AsyncRequester) -> None:
        self.account = AsyncAccountWithRawResponse(client)
        self.players = AsyncPlayersWithRawResponse(client)
        self.history = AsyncHistoryWithRawResponse(client)
        self.server = AsyncServerWithRawResponse(client)
        self.console = AsyncConsoleWithRawResponse(client)
        self.serverlog = AsyncServerLogWithRawResponse(client)
        self.events = AsyncEventsWithRawResponse(client)
        self.whitelist = AsyncWhitelistWithRawResponse(client)
        self.admins = AsyncAdminsWithRawResponse(client)
